async function fixture(env,pool,scenario,seed){const p=validateProbe(scenario.probe),game=await tokenFixture(env,pool,makeScenario(p,scenario),seed);game.records[0].constructionParameters.rawProbe=JSON.parse(JSON.stringify(p));game.records[0].fixtureConstruction='At first natural action window stage disclosed physical deck units in printed arenas, optional nativeShield/Weakness tokens, all planned hand cards in actual actor hand, up to24 remaining deck cards as ready resources per seat and ready existing resources, both bases damage0; no later state edits. Planned plays require real onCardPlayed+correct physical zone/parent+exact printed/aspect payment before script advances. Choose legal Play anyway on no-effect confirmation. Later scripts, regroup and committed terminal choices are real engine inputs. Completion policy excludes actual hand Support plays after focus assertions because generic Support donation projection is unsupported; full metadata and all legal action sets remain unchanged. Staged Rukh witnesses other-unique defeat only and make no Support lifecycle claim. Limits/window/registration IDs are read-only native observations.';game.witness.rawProbe=JSON.parse(JSON.stringify(p));game.witness.coverageObligationIds=[...(scenario.coverageObligationIds??[])];return game;}

